import math

def bisect_root(f, left, right, tol=1e-10, max_iter=100):
    if not all(math.isfinite(v) for v in (left, right, tol)):
        raise ValueError("端点和容差必须有限")
    if left >= right or tol <= 0:
        raise ValueError("要求 left < right 且 tol > 0")
    if type(max_iter) is not int or max_iter <= 0:
        raise ValueError("最大迭代次数必须是正整数")
    fl, fr = f(left), f(right)
    if not math.isfinite(fl) or not math.isfinite(fr):
        raise ValueError("端点函数值必须有限")
    if fl == 0:
        return left
    if fr == 0:
        return right
    if (fl < 0) == (fr < 0):
        raise ValueError("端点函数值必须异号")
    for _ in range(max_iter):
        mid = left / 2 + right / 2
        fm = f(mid)
        if not math.isfinite(fm):
            raise ValueError("区间内函数值必须有限")
        if fm == 0 or right / 2 - left / 2 <= tol:
            return mid
        if mid == left or mid == right:
            raise RuntimeError("浮点分辨率不足，无法继续缩小区间")
        if (fl < 0) != (fm < 0):
            right = mid
        else:
            left, fl = mid, fm
    raise RuntimeError("未达到容差")

print(bisect_root(lambda x: x*x - 2, 1, 2))

