from functools import wraps

def count_calls(function):
    calls = 0
    @wraps(function)
    def wrapper(*args, **kwargs):
        nonlocal calls
        calls += 1
        wrapper.calls = calls
        return function(*args, **kwargs)
    wrapper.calls = 0
    return wrapper

@count_calls
def area(width, height=1):
    return width * height

assert area(3, height=2) == 6
assert area(4) == 4
assert area.calls == 2
assert area.__name__ == "area"

